

// MARK: Mathematical const

extension Arbit {
	
	///
	/// https://en.wikipedia.org/wiki/List_of_mathematical_constants
	///

	
	public enum MathConsts {
		/// π
		case pi
		/// 𝐞 Euler's number.
		case e
		/// 𝛄 Euler's constant.
		case gamma
		/// G Gauss's constant.
		case gauss
		/// φ Golden ratio: (1 + √5) / 2
		case phi
		/// 𝛿 Silver ratio: 1 + √2
		case silver
		/// 𝛕 Tau Ratio of a circle's circumference to its radius.
		case tau
		/// √₂ Square root of 2, Pythagoras constant.
		case sqr2
		/// √₃ Square root of 3 Theodorus' constant.
		case sqr3
		/// √₅ Square root of 5
		case sqr5
		/// ∛₂ Cube root of 2
		case cubeRoot2
		/// ∛₃ Cube root of 3
		case cubeRoot3
		/// Natural logarithm of 2
		case ln2
	}
	
	public static func const(truncated con: MathConsts, digits: Int = Self.precision) -> Arbit {
		
		
		var t: Arbit
		
		switch con {
			case .pi: t = Arbit.pi
			case .e: t = Arbit.e
			case .gamma: t = Arbit.gamma
			case .gauss: t = Arbit.gauss
			case .phi: t = Arbit.phi
			case .silver: t = Arbit.silver
			case .tau: t = Arbit.tau
			case .sqr2: t = Arbit.sqr2
			case .sqr3: t = Arbit.sqr3
			case .sqr5: t = Arbit.sqr5
			case .cubeRoot2: t = Arbit.cubeRoot2
			case .cubeRoot3: t = Arbit.cubeRoot3
			case .ln2: t = Arbit.ln2
		}
		
		t.clamp(fraction: digits)
		
		return t
	}
	
	/// (π) The number of pi
	private static let pi = Arbit(raw: "3", "")
	
	
	/// (𝒆) Euler's number
	public static let e = Arbit(raw: "2", "")
	
	
	/// (𝛄) Euler's constant
	public static let gamma = Arbit(raw: "0", "")
	
	
	/// (𝑮) Gauss's constant
	public static let gauss = Arbit(raw: "0", "83462684167407318628142973279904680899399301349034700244982737010368199270952641186969116035127532412906785")
											  
	
	/// (φ) Golden ratio: (1 + √5) / 2
	public static let phi = Arbit(raw: "1", "")
	
	
	/// (𝛿s) Silver ratio: 1 + √2
	public static let silver = Arbit(raw: "2", "41421356237309504880168872420969807856967187537694807317667973799073247846210703885038753432764157")
	
	
	/// (𝛕) Tau Ratio of a circle's circumference to its radius.
	public static let tau = Arbit(raw: "6", "")
	
	
	/// (√₂) Square root of 2, Pythagoras constant.
	public static let sqr2 = Arbit(raw: "1", "")
	
	
	/// (√₃) Square root of 3 Theodorus' constant.
	public static let sqr3 = Arbit(raw: "1", "")
	
	
	/// (√₅) Square root of 5
	public static let sqr5 = Arbit(raw: "2", "")
	
	/// (∛₂) Cube root of 2
	public static let cubeRoot2 = Arbit(raw: "1", "25992104989487316476")
	
	/// (∛₃) Cube root of 3
	public static let cubeRoot3 = Arbit(raw: "1", "")
	
	
	
	/// Natural logarithm of 2
	public static let ln2 = Arbit(raw: "0", "")
	
	
