	/// The power of two
	public func pow2() -> Arbit {
		
		guard let key = self.asInt else { return Arbit.nan }
		
		if let string = Self.powersOfTwo[key] { return Arbit(raw: string) }
		
		let last = Self.powersOfTwo[Self.powersOfTwo.count]!
		
		var sum = Arbit(raw: last)
		for _ in stride(from: Self.powersOfTwo.count, to: key, by: 1) {
			sum *= 2
			// Self.powersOfTwo.updateValue(sum.integer, forKey: i) /// Fill up the cache...
		}
		return sum

	}
	
	/// The power of ten
	public func pow10() -> Arbit {
		
		guard let num = self.asInt else { return Arbit.nan }
		
		return Arbit(raw: "1" + String(repeating: "0", count: num) )
	}
	
	
	
